class Parent {
    static { System.out.print("P"); }
    { System.out.print("p"); }
    Parent() { System.out.print("1"); }
}
// 이 줄을 고쳐 Ticket이 Parent를 상속하게 하세요.
// extends Parent: Ticket을 만들기 전에 Parent 부분부터 준비해요.
class Ticket extends Parent {
    static { System.out.print("C"); }
    { System.out.print("c"); }
    Ticket() { System.out.print("2"); }
}
public class Main {
    public static void main(String[] args) {
        int count = 1;
        for (int i = 0; i < count; i++) {
            new Ticket();
        }
        System.out.println();
    }
}

