class Ticket {
    static int next = 1;
    // 객체마다 먼저 번호를 받아요.
    int id = next++;
    // 필드 초기화 다음에 생성자를 실행해요.
    Ticket() { next += 10; }
}

public class Main {
    public static void main(String[] args) {
        Ticket a = new Ticket();
        Ticket b = new Ticket();
        System.out.println(a.id + ":" + b.id + ":" + Ticket.next);
    }
}

